// Usage:
//
//	go run . -out ../../../platform/compositions/appdatabase-postgres.yaml
package main

import (
	"flag"
	"fmt"
	"os"

	"sigs.k8s.io/yaml"
)

const (
	compositionName = "appdatabase.postgres.platform.saas.example"
	providerConfigFmt = "rds-%s"
	connectionSecretNamespace = "crossplane-system"
	fnInputAPIVersion = "appdatabase.fn.saas.example/v1beta1"
)

const banner = `# ─────────────────────────────────────────────────────────────────────────────
# GENERATED by scripts/gen/appdatabase-composition (go run ./scripts/gen/...).
# Modern Crossplane function-pipeline Composition — do not edit by hand.
# Change the generator and re-run 'make composition'.
# ─────────────────────────────────────────────────────────────────────────────
`

// --- Composition (apiextensions.crossplane.io/v1), Pipeline mode ------------

type composition struct {
	APIVersion string          `json:"apiVersion"`
	Kind       string          `json:"kind"`
	Metadata   metadata        `json:"metadata"`
	Spec       compositionSpec `json:"spec"`
}

type metadata struct {
	Name   string            `json:"name"`
	Labels map[string]string `json:"labels,omitempty"`
}

type compositionSpec struct {
	CompositeTypeRef typeRef `json:"compositeTypeRef"`
	// Mode: Pipeline is what replaces the legacy `resources` array.
	Mode string `json:"mode"`
	// Aggregated connection secret target (preserves prior behaviour: the
	// claim gets username/password/host/database).
	WriteConnectionSecretsToNamespace string         `json:"writeConnectionSecretsToNamespace,omitempty"`
	Pipeline                          []pipelineStep `json:"pipeline"`
}

type typeRef struct {
	APIVersion string `json:"apiVersion"`
	Kind       string `json:"kind"`
}

type pipelineStep struct {
	Step        string      `json:"step"`
	FunctionRef functionRef `json:"functionRef"`
	Input       any         `json:"input,omitempty"`
}

type functionRef struct {
	Name string `json:"name"`
}

type appdatabaseInput struct {
	APIVersion                string `json:"apiVersion"`
	Kind                      string `json:"kind"`
	ProviderConfigFormat      string `json:"providerConfigFormat"`
	ConnectionSecretNamespace string `json:"connectionSecretNamespace"`
}

func build() composition {
	return composition{
		APIVersion: "apiextensions.crossplane.io/v1",
		Kind:       "Composition",
		Metadata: metadata{
			Name: compositionName,
			Labels: map[string]string{
				"provider": "postgresql",
				"type":     "appdatabase",
			},
		},
		Spec: compositionSpec{
			CompositeTypeRef: typeRef{
				APIVersion: "platform.saas.example/v1alpha1",
				Kind:       "XAppDatabase",
			},
			Mode:                              "Pipeline",
			WriteConnectionSecretsToNamespace: connectionSecretNamespace,
			Pipeline: []pipelineStep{
				{
					// Our custom Go function composes Role + Database + Grant
					// (+ Extensions) from the claim parameters.
					Step:        "appdatabase",
					FunctionRef: functionRef{Name: "function-appdatabase"},
					Input: appdatabaseInput{
						APIVersion:                fnInputAPIVersion,
						Kind:                      "Input",
						ProviderConfigFormat:      providerConfigFmt,
						ConnectionSecretNamespace: connectionSecretNamespace,
					},
				},
				{
					// Derives XR/claim readiness from the composed resources,
					// which Resources mode used to do implicitly.
					Step:        "ready",
					FunctionRef: functionRef{Name: "function-auto-ready"},
				},
			},
		},
	}
}

func main() {
	out := flag.String("out", "", "output file (default: stdout)")
	flag.Parse()

	doc, err := yaml.Marshal(build())
	if err != nil {
		fmt.Fprintln(os.Stderr, "marshal:", err)
		os.Exit(1)
	}
	content := banner + "---\n" + string(doc)

	if *out == "" {
		fmt.Print(content)
		return
	}
	if err := os.WriteFile(*out, []byte(content), 0o644); err != nil {
		fmt.Fprintln(os.Stderr, "write:", err)
		os.Exit(1)
	}
	fmt.Fprintf(os.Stderr, "rendered composition -> %s\n", *out)
}
